	if aHash == "" || bHash == "" || aHash == bHash {
		return nil
	}
	return fmt.Errorf("eval run_config.tasks_sha256 values differ (A=%s, B=%s); rerun over the same tasks file or pass --allow-task-hash-mismatch", aHash, bHash)
}

