	cmd.Flags().StringVar(&out, "out", "", "Verdicts path (default <run>/judge.jsonl)")
	_ = cmd.MarkFlagRequired("run")
	return cmd
}

func loadDistillEvalJudgeLines(path string) (map[string]distillEvalJudgeLine, error) {
	f, err := os.Open(path)
