		return &v
	}
	goldenKeeps, judgeKeeps, combinedKeeps, combinedN := 0, 0, 0, 0
	for _, id := range runOrder {
		label, hasLabel := labels[id]
		j, hasJudge := judged[id]
		if hasLabel {
			precision.GoldenN++
			if label.Verdict == "keep" {
				goldenKeeps++
			}
		}
		if hasJudge {
			precision.JudgeN++
			if j.Verdict == "keep" {
				judgeKeeps++
			}
		}
		switch {
		case hasLabel:
			combinedN++
			if label.Verdict == "keep" {
