	cmd := newDistillCommand(Options{})
	flag := cmd.Flags().Lookup("raw-facts-out")
	if flag == nil {
		t.Fatal("--raw-facts-out flag missing")
	}
	if !flag.Hidden {
		t.Error("--raw-facts-out must be hidden")
	}
}

