24	// distillEvalExec is the shell-out seam: every child process the eval harness
25	// spawns (refresh sessions, distill) goes through it so tests can intercept.
26	// The child is the current binary; env replaces the process environment.
27	var distillEvalExec = func(ctx context.Context, dir string, env []string, args ...string) ([]byte, error) {
28		exe, err := os.Executable()
29		if err != nil {
30			return nil, fmt.Errorf("resolve own executable: %w", err)
31		}
32		cmd := exec.CommandContext(ctx, exe, args...)
33		cmd.Dir = dir
34		cmd.Env = env
35		out, err := cmd.CombinedOutput()
36		if err != nil {
37			tail := out
38			if len(tail) > 2000 {
39				tail = tail[len(tail)-2000:]
40			}
41			return out, fmt.Errorf("%s: %w\n%s", args[0], err, tail)
42		}
43		return out, nil
44	}
45	
46	// distillEvalChildEnv builds the child environment: the parent's, minus any
47	// XDG data/state/cache and distill override leakage, plus the sandbox and the
48	// variant's overrides. XDG_CONFIG_HOME is inherited on purpose — the child's
49	// agent (claude/codex) needs the user's auth and config.
50	func distillEvalChildEnv(sandbox string, extra map[string]string) []string {
51		drop := map[string]bool{
52			"XDG_DATA_HOME": true, "XDG_STATE_HOME": true, "XDG_CACHE_HOME": true,
53			envDistillTemplate: true, envFactsMaxPerChunk: true,
54		}
55		var env []string
56		for _, kv := range os.Environ() {
57			key, _, ok := strings.Cut(kv, "=")
58			if ok && drop[key] {
59				continue
60			}
61			env = append(env, kv)
62		}
63		env = append(env,
64			"XDG_DATA_HOME="+filepath.Join(sandbox, "data"),
65			"XDG_STATE_HOME="+filepath.Join(sandbox, "state"),
66			"XDG_CACHE_HOME="+filepath.Join(sandbox, "cache"),
67		)
68		keys := make([]string, 0, len(extra))
69		for k := range extra {
70			keys = append(keys, k)
71		}
72		sort.Strings(keys)
73		for _, k := range keys {
74			env = append(env, k+"="+extra[k])
75		}
76		return env
77	}
