143			Use:   "corpus",
144			Short: "Build a fixed eval corpus from this repo's sessions",
145			RunE: func(cmd *cobra.Command, args []string) error {
146				if out == "" {
147					home, err := os.UserHomeDir()
148					if err != nil {
149						return err
150					}
151					out = filepath.Join(home, ".entire-brain-eval", filepath.Base(distillEvalRepoRoot(opts)))
152				}
153				sandbox := filepath.Join(out, "sandbox")
154				if err := os.MkdirAll(sandbox, 0o700); err != nil {
155					return err
156				}
157				env := distillEvalChildEnv(sandbox, nil)
158				brainDir, err := distillEvalExportSessions(cmd.Context(), opts, sandbox, env)
159				if err != nil {
160					return err
161				}
162				manifest, err := loadBrainManifest(brainDir)
163				if err != nil {
164					return err
165				}
166				if manifest.Sources == nil || manifest.Sources.Sessions == nil {
167					return errors.New("sandbox manifest has no sessions")
168				}
169				var entries []distillEvalCorpusEntry
170				for _, s := range manifest.Sources.Sessions.Sessions {
171					info, err := os.Stat(filepath.Join(brainDir, filepath.FromSlash(s.TranscriptPath)))
172					if err != nil || info.Size() == 0 {
173						continue
174					}
175					entries = append(entries, distillEvalCorpusEntry{
176						SessionID:      s.SessionID,
177						Branch:         resolveDistillBranch(manifest, s),
178						TranscriptPath: s.TranscriptPath,
179						RawBytes:       int(info.Size()),
180						// ponytail: chunk estimate assumes preprocessing is
181						// roughly size-preserving; exact counts come from the raw
182						// run's chunk lines.
183						Chunks: int((info.Size() + defaultDistillChunkSize - 1) / defaultDistillChunkSize),
184					})
185				}
186				if len(entries) == 0 {
187					return errors.New("no non-empty session transcripts in sandbox export")
188				}
189				sort.Slice(entries, func(i, j int) bool {
190					if entries[i].RawBytes != entries[j].RawBytes {
191						return entries[i].RawBytes < entries[j].RawBytes
192					}
193					return entries[i].SessionID < entries[j].SessionID
194				})
195				if sessionsN > 0 && len(entries) > sessionsN {
196					entries = entries[:sessionsN]
197				}
198				for i := 0; i < goldenN && i < len(entries); i++ {
199					entries[i].Golden = true
200				}
201				ids := make([]string, len(entries))
202				for i, e := range entries {
203					ids[i] = e.SessionID
204				}
205				corpus := distillEvalCorpus{
206					RepoKey:      brainRepoKeyBestEffort(brainDir),
207					CreatedAt:    opts.Now(),
208					CorpusSHA256: distillEvalCorpusSHA(ids),
209					Sessions:     entries,
210				}
211				data, err := json.MarshalIndent(corpus, "", "  ")
212				if err != nil {
213					return err
214				}
215				path := filepath.Join(out, "corpus.json")
216				if err := os.WriteFile(path, append(data, '\n'), 0o600); err != nil {
217					return err
218				}
219				fmt.Fprintf(cmd.OutOrStdout(), "corpus: %d sessions (%d golden) → %s\n", len(entries), min(goldenN, len(entries)), path)
220				return nil
221			},
