// The judge spawns claude-code, which refuses to start nested while CLAUDECODE
// is set; the judge must attach distill's sanitized child env to the context,
// exactly like the distill pipeline does.
func TestDistillEvalJudgeSanitizesClaudeChildEnv(t *testing.T) {
	t.Setenv("CLAUDECODE", "1")
	runDir := writeJudgeFixtureRun(t)
	var childEnv []string
	restore := distillEvalJudgeRunnerFor
	distillEvalJudgeRunnerFor = func(agent string) distillAgentRunner {
		return func(ctx context.Context, dir string, args []string, input []byte, timeout time.Duration) (string, error) {
			if env, ok := ctx.Value(distillChildEnvKey{}).([]string); ok {
				childEnv = env
			}
			return "1 keep\n2 keep\n3 keep\n", nil
		}
	}
	defer func() { distillEvalJudgeRunnerFor = restore }()
	if _, err := runDistillEvalCommand(t, t.TempDir(), "judge", "--run", runDir, "--out", filepath.Join(runDir, "judge.jsonl")); err != nil {
		t.Fatalf("judge: %v", err)
	}
	if childEnv == nil {
		t.Fatal("judge context carries no sanitized claude child env")
	}
	for _, kv := range childEnv {
		if strings.HasPrefix(kv, "CLAUDECODE=") {
			t.Errorf("CLAUDECODE leaked into judge child env")
		}
	}
}

