		}
		// s-old predates the window; s-dup appears on two branches.
		sessions := []exportSession{
			{SessionID: "s-old", Branch: "main", TranscriptPath: "sessions/main/s-old.jsonl", CreatedAt: now.AddDate(0, 0, -10)},
			{SessionID: "s-new", Branch: "main", TranscriptPath: "sessions/main/s-new.jsonl", CreatedAt: now.AddDate(0, 0, -1)},
			{SessionID: "s-dup", Branch: "main", TranscriptPath: "sessions/main/s-dup.jsonl", CreatedAt: now.AddDate(0, 0, -1)},
			{SessionID: "s-dup", Branch: "feature", TranscriptPath: "sessions/branches/feature/s-dup.jsonl", CreatedAt: now.AddDate(0, 0, -1)},
		}
		for _, s := range sessions {
			p := filepath.Join(brainDir, filepath.FromSlash(s.TranscriptPath))
			if err := os.MkdirAll(filepath.Dir(p), 0o700); err != nil {
				t.Fatal(err)
			}
			if err := os.WriteFile(p, []byte("turn one\n"), 0o600); err != nil {
				t.Fatal(err)
			}
		}
		manifest := exportManifest{
			SchemaVersion: brainManifestSchemaVersion, GeneratedAt: now, DefaultBranch: "main",
			Sources: &brainSources{Sessions: &sessionSourceManifest{GeneratedAt: now, DefaultBranch: "main", Sessions: sessions}},
		}
		if err := writeBrainManifestAndReadme(brainDir, manifest); err != nil {
			t.Fatal(err)
		}
		return nil, nil
	}
	defer func() { distillEvalExec = restore }()

	outDir := t.TempDir()
	if _, err := runDistillEvalCommand(t, t.TempDir(), "corpus", "--out", outDir, "--since", "2026-10-22", "--golden", "0"); err != nil {
		t.Fatalf("corpus: %v", err)
	}
	data, err := os.ReadFile(filepath.Join(outDir, "corpus.json"))
	if err != nil {
		t.Fatal(err)
	}
	var corpus distillEvalCorpus
	if err := json.Unmarshal(data, &corpus); err != nil {
		t.Fatal(err)
	}
	var ids []string
	for _, s := range corpus.Sessions {
		ids = append(ids, s.SessionID)
	}
	if len(ids) != 2 {
		t.Fatalf("want 2 sessions (window-filtered, deduped), got %v", ids)
	}
	seen := map[string]bool{}
	for _, id := range ids {
		if id == "s-old" {
			t.Errorf("session before --since included: %v", ids)
		}
		if seen[id] {
			t.Errorf("duplicate session id in corpus: %v", ids)
		}
		seen[id] = true
	}
}

